export type ComponentRecipeName = keyof typeof COMPONENT_RECIPES;
export const COMPONENT_RECIPE_COUNT = Object.keys(COMPONENT_RECIPES).length;
export const COMPONENT_RECIPE_PART_COUNT = Object.values(COMPONENT_RECIPES)
  .reduce((count, recipe) => count + Object.keys(recipe.partSelectors).length, 0);

export function getComponentRecipe(name: ComponentRecipeName) {
  return COMPONENT_RECIPES[name];
}
